# This code has been fully generated by an AI.
"""Start: Kamera, Modell, Server und die beiden Fenster Bühne und Bedienung."""

import argparse
import logging
import os
import threading
import time

import uvicorn

from .app import App
from .config import settings
from .server import create_server


def main() -> None:
    parser = argparse.ArgumentParser(prog="hebocon")
    parser.add_argument("--no-window", action="store_true", help="nur Server, Bedienung im Browser öffnen")
    parser.add_argument("--camera", help="Kameraquelle überschreiben (Index, URL oder Datei)")
    args = parser.parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")
    # aioice meldet jeden ICE-Kandidaten einzeln und begräbt so die eigenen Meldungen.
    logging.getLogger("aioice").setLevel(logging.WARNING)
    if args.camera:
        settings.camera = args.camera

    app = App(settings)
    app.start()
    server = uvicorn.Server(uvicorn.Config(create_server(app), host="127.0.0.1", port=settings.port,
                                           log_level="warning"))
    url = f"http://127.0.0.1:{settings.port}"

    if args.no_window:
        logging.info("Bedienung: %s  Bühne: %s/stage", url, url)
        try:
            server.run()
        finally:
            app.stop()
        return

    # Ohne Klick ins Bühnenfenster blockiert WebView2 sonst Memes mit Ton; die Overscroll-Option
    # setzt pywebview selbst und ginge durch die Variable verloren.
    os.environ.setdefault("WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS",
                          "--disable-features=ElasticOverscroll --autoplay-policy=no-user-gesture-required")
    import webview

    threading.Thread(target=server.run, name="server", daemon=True).start()
    while not server.started:
        time.sleep(0.05)
    webview.create_window("Hebocon Bühne", f"{url}/stage", width=1280, height=760,
                          fullscreen=settings.stage_fullscreen, background_color="#000000")
    webview.create_window("Hebocon Bedienung", url, width=1300, height=900)
    try:
        webview.start()
    finally:
        server.should_exit = True
        app.stop()


if __name__ == "__main__":
    main()
